function longestNiceSubarray(nums) {
  let used = 0;
  let left = 0;
  let best = 0;
  for (let right = 0; right < nums.length; right++) {
    while ((used & nums[right]) !== 0) {
      used ^= nums[left];
      left++;
    }
    used |= nums[right];
    best = Math.max(best, right - left + 1);
  }
  return best;
}

