function longestNiceSubarray(nums) {
  const n = nums.length;
  let longest = 1;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      let nice = true;
      for (let a = i; a <= j && nice; a++)
        for (let b = a + 1; b <= j && nice; b++)
          if ((nums[a] & nums[b]) !== 0) nice = false;
      if (!nice) break;
      longest = Math.max(longest, j - i + 1);
    }
  }
  return longest;
}

