function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const LIMIT = 1000000000;
  // A value made of one to three random bits among bits 0..29, kept within 10^9.
  const sparse = (topBit, maxBits) => {
    for (;;) {
      let value = 0;
      for (let k = int(1, maxBits); k > 0; k--) value |= 1 << int(0, topBit);
      if (value >= 1 && value <= LIMIT) return value;
    }
  };
  if (size === 'small') {
    const n = int(1, 10);
    const mode = int(0, 2);
    const pick = () => mode === 0 ? int(1, 16) : mode === 1 ? sparse(4, 2) : int(1, LIMIT);
    return [Array.from({ length: n }, pick)];
  }
  const n = int(1800, 2000);
  const maxBits = int(1, 3);
  const nums = Array.from({ length: n }, () => sparse(29, maxBits));
  // Sometimes plant all 30 single-bit values side by side, the longest possible nice block.
  if (rand() < 0.5) {
    const bits = Array.from({ length: 30 }, (_, b) => 2 ** b);
    for (let k = bits.length - 1; k > 0; k--) { const r = int(0, k); [bits[k], bits[r]] = [bits[r], bits[k]]; }
    const start = int(0, n - 30);
    for (let k = 0; k < 30; k++) nums[start + k] = bits[k];
  }
  return [nums];
}
